pub fn run_frame(&mut self, frame: &mut Frame) -> Result<Completion, Value> {
    if let Some(e) = frame.pending_throw.take() {
        if !self.handle_throw(frame, e.clone()) {
            return Err(e);
        }
    }
    loop {
        match self.run_inner(frame) {
            Ok(c) => return Ok(c),
            Err(e) => {
                if !self.handle_throw(frame, e.clone()) {
                    return Err(e);
                }

