let n = 0;
const server = Lumen.serve({ port, hostname: "127.0.0.1", onListen(info) { console.log("listening", JSON.stringify(info)); } }, async (req) => {
  n++;
  const u = new URL(req.url);
  console.log("req", n, req.method, req.url, JSON.stringify([...req.headers]), "signal:", String(req.signal), "bodyUsed:", req.bodyUsed);
  const t = await req.text();
  console.log("body:", JSON.stringify(t));
