    case "/text": return new Response("hello");
    case "/json": return Response.json({ a: 1 });
    case "/status": return new Response("nf", { status: 404, statusText: "Nope", headers: [["X-B", "2"], ["x-a", "1"], ["Set-Cookie", "a=1"]] });
