function d(v) {
  if (!ArrayBuffer.isView(v)) return String(v);
  return v.constructor.name + "(off=" + v.byteOffset + ",len=" + v.byteLength + ",buflen=" + v.buffer.byteLength + ")[" + Array.from(new Uint8Array(v.buffer, v.byteOffset, v.byteLength)).join(",") + "]";
}
(async () => {
  const rs = new ReadableStream({
    type: "bytes",
    start(c) {
      c.enqueue(new Uint8Array([1, 2, 3]));
      c.enqueue(new Uint8Array([4, 5]));
      c.enqueue(new Uint8Array([6, 7, 8, 9]));
      c.close();
    },
  });
  const r = rs.getReader({ mode: "byob" });
  const buf = new Uint8Array(4);
  let res = await r.read(buf);
  console.log("1:", res.done, d(res.value), "same buffer:", res.value.buffer === buf.buffer, d(buf));
  res = await r.read(new Uint8Array(2));
  console.log("2:", res.done, d(res.value));
  res = await r.read(new Uint16Array(2));
  console.log("3:", res.done, d(res.value));
  res = await r.read(new Uint8Array(10));
  console.log("4:", res.done, d(res.value));
  res = await r.read(new Uint8Array(10));
  console.log("5:", res.done, d(res.value));
  console.log("chunks left:", rs._chunks.length);
  // odd bytes into Uint16Array
  const rs2 = new ReadableStream({ type: "bytes", start(c) { c.enqueue(new Uint8Array([1, 2, 3])); c.close(); } });
  const r2 = rs2.getReader({ mode: "byob" });
  try {
    res = await r2.read(new Uint16Array(4));
    console.log("odd:", res.done, d(res.value), "remaining:", rs2._chunks.length, rs2._chunks[0] && d(rs2._chunks[0]));
  } catch (e) { console.log("odd err:", e.name, e.message); }
  // default reader on byte stream
  const rs3 = new ReadableStream({ type: "bytes", start(c) { c.enqueue(new Uint16Array([258])); c.close(); } });
  const r3 = rs3.getReader();
  res = await r3.read();
  console.log("default on bytes:", d(res.value));
  // pull with byobRequest
  let pulls = 0;
  const rs4 = new ReadableStream({
    type: "bytes",
