  const s1 = new ReadableStream({ start(c) { c.enqueue(new Uint8Array([65])); c.close(); } });
  s1.getReader();
  try { console.log("locked text:", await new Response(s1).text()); } catch (e) { console.log("locked text ERR", e.name + ": " + e.message); }
  // after drain, locked?
  const s2 = new ReadableStream({ start(c) { c.enqueue(new Uint8Array([66])); c.close(); } });
  const r2 = new Response(s2);
  console.log("drain:", await r2.text(), "locked after:", s2.locked, "state:", s2._state, "body after:", String(r2.body), r2.body === s2);
  // text then body read
  const r3 = new Response("abc");
  await r3.text();
  const rd3 = r3.body.getReader();
  const x3 = await rd3.read();
  console.log("body after text:", x3.done, String(x3.value));
  // body read then text
  const r4 = new Response("abc");
  const b4 = r4.body;
  console.log("bodyUsed after body access:", r4.bodyUsed);
  try { console.log("text after body access:", await r4.text()); } catch (e) { console.log("ERR", e.message); }
  // stream body partially read by user then text
  const s5 = new ReadableStream({ start(c) { c.enqueue(new Uint8Array([67])); c.enqueue(new Uint8Array([68])); c.close(); } });
  const r5 = new Response(s5);
  const rd5 = r5.body.getReader();
  await rd5.read();
  rd5.releaseLock();
  console.log("partial then text:", await r5.text());
  // stream body: enqueue strings mixed
  const s6 = new ReadableStream({ start(c) { c.enqueue("é"); c.enqueue(new Uint8Array([0xe2, 0x82])); c.enqueue(new Uint8Array([0xac])); c.close(); } });
  console.log("mixed:", await new Response(s6).text());
