  const r7 = new Response('{"a":[1,2]}');
  const ab = await r7.arrayBuffer();
  console.log("ab:", Object.prototype.toString.call(ab), ab.byteLength);
  const by = await new Response("hey").bytes();
  console.log("bytes:", by.constructor.name, by.length, Object.prototype.toString.call(by));
  const bl = await new Response("hey", { headers: { "content-type": "text/zzz" } }).blob();
  console.log("blob:", Object.prototype.toString.call(bl), bl.size, bl.type);
  const js = await new Response('{"a":[1,2]}').json();
  console.log("json:", JSON.stringify(js));
  try { await new Response("not json").json(); } catch (e) { console.log("json err:", e.name + ": " + e.message); }
  try { await new Response("").json(); } catch (e) { console.log("json empty err:", e.name + ": " + e.message); }
  const u8 = new Uint8Array([1, 2, 3]);
  const by2 = await new Response(u8).bytes();
  console.log("bytes same:", by2 === u8);
  const ab2 = await new Response(u8.subarray(1)).arrayBuffer();
  console.log("ab sub:", ab2.byteLength, new Uint8Array(ab2).join());
  const fd = await new Response("a=1&b=%20x&a=2", { headers: { "content-type": "application/x-www-form-urlencoded" } }).formData();
  console.log("formData:", Object.prototype.toString.call(fd), JSON.stringify([...fd]));
  try { await new Response("x").formData(); } catch (e) { console.log("fd err:", e.name + ": " + e.message); }
  try { await new Response("x", { headers: { "content-type": "multipart/form-data" } }).formData(); } catch (e) { console.log("fd err2:", e.name + ": " + e.message); }
  const f = new FormData(); f.append("a", "1"); f.append("file", new Blob(["content"], { type: "text/plain" }), "f.txt"); f.append("b", "two");
  const r8 = new Response(f);
  const fd2 = await r8.formData();
  console.log("multipart roundtrip:", JSON.stringify([...fd2].map(([k, v]) => [k, typeof v === "string" ? v : Object.prototype.toString.call(v) + ":" + v.name + ":" + v.type + ":" + v.size])));
  const mp = "--XYZ\r\nContent-Disposition: form-data; name=\"field\"\r\n\r\nvalue1\r\n--XYZ\r\nContent-Disposition: form-data; name=\"up\"; filename=\"a.bin\"\r\nContent-Type: application/octet-stream\r\n\r\nBIN\r\n--XYZ\r\nContent-Disposition: form-data; name=\"nofile\"\r\nContent-Type: text/x\r\n\r\nNF\r\n--XYZ--\r\n";
  const fd3 = await new Response(mp, { headers: { "content-type": "multipart/form-data; boundary=XYZ" } }).formData();
  console.log("manual multipart:", JSON.stringify([...fd3].map(([k, v]) => [k, typeof v === "string" ? v : Object.prototype.toString.call(v) + ":" + v.name + ":" + v.type + ":" + v.size])));
  const fd4 = await new Response(mp, { headers: { "content-type": "multipart/form-data; boundary=\"XYZ\"; charset=x" } }).formData();
  console.log("quoted boundary:", fd4.get("field"));
})();

