fn array_buffer_ctor(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    if a.new_target.is_none() {
        return vm.throw_type("Constructor ArrayBuffer requires 'new'");
    }
    let len = vm.to_index(&a.arg(0))?;
    let mut max = None;
    if let Value::Obj(o) = a.arg(1) {
        let m = vm.get_str(&o, "maxByteLength")?;
        if !m.is_undefined() {
            let ml = vm.to_index(&m)?;
            if len > ml {
                return vm.throw_range("Invalid array buffer max length");
            }
            max = Some(ml);
        }
    }
    let proto = vm.proto_from_nt(&a.new_target, &vm.intr.array_buffer_proto.clone())?;
    if len > 0x7fff_ffff {
        return vm.throw_range("Array buffer allocation failed");
    }
    let data = Rc::new(RefCell::new(BufferData { bytes: vec![0; len], detached: false, max_len: max, shared: false }));
    Ok(Value::Obj(Obj::with_class(Some(proto), ObjKind::ArrayBuffer(data), "ArrayBuffer")))
}

