fn strategy_construct(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let fallback = {
        let c = ctx();
        let is_bl = matches!(&a.callee.borrow().props.get(&key("name")), Some(Prop::Data { value: Value::Str(s), .. }) if s.eq_str("ByteLengthQueuingStrategy"));
        if is_bl {
            c.bl_proto.clone()
        } else {
            c.cq_proto.clone()
        }
    };
    let this = new_this(vm, a, &fallback)?;
    let hwm = get(vm, &a.arg(0), "highWaterMark")?;
    put(vm, &this, "highWaterMark", hwm)?;
    Ok(this)
}

fn bl_size(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    get(vm, &a.arg(0), "byteLength")
}

