old = '''    let et = global(vm, "EventTarget");
    if matches!(&et, Value::Obj(o) if o.is_constructor()) {
        let nt = Value::Obj(a.new_target.clone().unwrap());
        return vm.construct(&et, &[], Some(&nt));
